INSERT INTO clinlims.observation_history_type (id, type_name, description, lastupdated)
SELECT nextval('clinlims.observation_history_type_seq'), 'CyCollectionMethod', 'CY_COLLECTION_METHOD', now()
WHERE NOT EXISTS (SELECT 1 FROM clinlims.observation_history_type WHERE type_name = 'CyCollectionMethod');
